package local.aicenter.core;
public final class ReviewScheduleTest {
 private static int checks;
 private static void yes(boolean condition){checks++;if(!condition)throw new AssertionError("check "+checks);}
 private static void rejects(Runnable r){checks++;try{r.run();throw new AssertionError("accepted invalid input");}catch(IllegalArgumentException expected){}}
 public static void main(String[] args){long now=1_000_000;ReviewSchedule.State first=ReviewSchedule.answer(null,true,now);yes(first.stage==1&&first.due==now+ReviewSchedule.DAY&&first.attempts==1&&first.errors==0);yes(!ReviewSchedule.due(first,first.due-1));yes(ReviewSchedule.due(first,first.due));ReviewSchedule.State early=ReviewSchedule.answer(first,true,now+100);yes(early.stage==1&&early.due==first.due&&early.attempts==2);ReviewSchedule.State next=ReviewSchedule.answer(early,true,early.due);yes(next.stage==2&&next.due==early.due+3*ReviewSchedule.DAY);ReviewSchedule.State error=ReviewSchedule.answer(next,false,next.due);yes(error.stage==0&&error.errors==1&&!error.lastCorrect&&error.due==next.due+600000);ReviewSchedule.State correction=ReviewSchedule.answer(error,true,error.updated+1);yes(correction.stage==0&&correction.lastCorrect&&correction.due==error.due);ReviewSchedule.State restarted=ReviewSchedule.answer(correction,true,correction.due);yes(restarted.stage==1&&restarted.due==correction.due+ReviewSchedule.DAY);ReviewSchedule.State repeated=restarted;for(int i=0;i<20;i++)repeated=ReviewSchedule.answer(repeated,true,repeated.due);yes(repeated.stage==6);yes(ReviewSchedule.answer(null,true,Long.MAX_VALUE).due==Long.MAX_VALUE);yes(ReviewSchedule.answer(null,false,0).due==600000);rejects(()->ReviewSchedule.answer(null,true,-1));rejects(()->new ReviewSchedule.State(1,2,0,0,0,false));rejects(()->new ReviewSchedule.State(1,0,7,0,0,false));rejects(()->ReviewSchedule.due(first,-1));
 for(CapabilityCourse.Lesson lesson:CapabilityCourse.LESSONS)for(int i=0;i<lesson.questions.length;i++){String id=CapabilityCourse.questionId(lesson,i);yes(CapabilityCourse.question(id)==lesson.questions[i]);yes(CapabilityCourse.questionLesson(id)==lesson);}rejects(()->CapabilityCourse.question("cpk.v1.invalid.0"));rejects(()->CapabilityCourse.questionId(CapabilityCourse.LESSONS[0],-1));System.out.println("PASS review schedule and stable question identities: "+checks+" assertions (host only)");}
}
